(SELECT '{shard}' AS s, id AS i, result AS r, country_code AS c, create_time AS t, CASE WHEN JSON_VALID(request_strategy_engine) AND JSON_VALID(JSON_UNQUOTE(JSON_EXTRACT(request_strategy_engine, '$.para'))) AND COALESCE(JSON_UNQUOTE(JSON_EXTRACT(CAST(JSON_UNQUOTE(JSON_EXTRACT(request_strategy_engine, '$.para')) AS JSON), '$.email')), '') NOT IN ('', 'null') THEN 1 ELSE 0 END AS m FROM luckyus_iriskcontrolservice.{tbl} WHERE create_time >= '{utc_start}' AND create_time < '{utc_end}' AND scene_id = '{scene}')
